def canMakeSquare(grid):
    # Check all possible 2x2 squares in the 3x3 grid
    # There are 4 possible 2x2 squares: top-left, top-right, bottom-left, bottom-right

    # Check top-left 2x2 square (positions [0][0], [0][1], [1][0], [1][1])
    if hasSameColorSquare(grid, 0, 0):
        return True

    # Check top-right 2x2 square (positions [0][1], [0][2], [1][1], [1][2])
    if hasSameColorSquare(grid, 0, 1):
        return True

    # Check bottom-left 2x2 square (positions [1][0], [1][1], [2][0], [2][1])
    if hasSameColorSquare(grid, 1, 0):
        return True

    # Check bottom-right 2x2 square (positions [1][1], [1][2], [2][1], [2][2])
    if hasSameColorSquare(grid, 1, 1):
        return True

    return False

def hasSameColorSquare(grid, start_row, start_col):
    # Count occurrences of 'B' and 'W' in the 2x2 square
    b_count = 0
    w_count = 0

    for i in range(2):
        for j in range(2):
            if grid[start_row + i][start_col + j] == 'B':
                b_count += 1
            else:
                w_count += 1

    # If we already have a 2x2 square of same color
    if b_count == 4 or w_count == 4:
        return True

    # If we can make a 2x2 square by changing at most one cell
    # We need 3 of one color and 1 of another - then we can change the different one
    if b_count == 3 or w_count == 3:
        return True

    return False
