def numberOfSpecialChars(word):
    # Count frequency of each character
    char_count = {}
    for char in word:
        char_count[char] = char_count.get(char, 0) + 1

    # Find special letters (appear in both lowercase and uppercase)
    special_count = 0
    processed = set()

    for char in word:
        lower_char = char.lower()

        # Skip if we've already processed this letter
        if lower_char in processed:
            continue

        # Check if both lowercase and uppercase versions exist
        if char_count.get(lower_char, 0) > 0 and char_count.get(lower_char.upper(), 0) > 0:
            special_count += 1
            processed.add(lower_char)

    return special_count
