    import sys
    from itertools import product

    def read_polyomino():
        grid = []
        for _ in range(4):
            line = input().strip()
            grid.append(list(line))
        return grid

    def get_input():
        polyominoes = []
        for _ in range(3):
            polyominoes.append(read_polyomino())
        return polyominoes

    def rotate_90(grid):
        """Rotate the grid 90 degrees clockwise"""
        n = len(grid)
        return [[grid[n-1-j][i] for j in range(n)] for i in range(n)]

    def normalize_shape(shape):
        """Convert shape to a canonical form with minimum coordinates at (0,0)"""
        positions = []
        for i in range(4):
            for j in range(4):
                if shape[i][j] == '#':
                    positions.append((i, j))

        if not positions:
            return set()

        # Find the top-left corner
        min_i = min(pos[0] for pos in positions)
        min_j = min(pos[1] for pos in positions)

        # Normalize positions
        normalized = set((i - min_i, j - min_j) for i, j in positions)
        return normalized

    def get_all_orientations(shape):
        """Get all possible orientations (rotations) of a shape"""
        orientations = []
        current = [row[:] for row in shape]

        for _ in range(4):  # 4 rotations: 0°, 90°, 180°, 270°
            orientations.append([row[:] for row in current])
            current = rotate_90(current)

        # Remove duplicates by comparing normalized shapes
        unique_orientations = []
        seen = set()

        for orient in orientations:
            norm = normalize_shape(orient)
            if str(norm) not in seen:
                seen.add(str(norm))
                unique_orientations.append(orient)

        return unique_orientations

    def place_polyomino(grid, shape, start_i, start_j):
        """Try to place the shape at position (start_i, start_j) on the grid"""
        new_grid = [row[:] for row in grid]
        shape_positions = []

        for i in range(4):
            for j in range(4):
                if shape[i][j] == '#':
                    shape_positions.append((i, j))

        # Check if placement is valid
        for si, sj in shape_positions:
            ni, nj = start_i + si, start_j + sj
            if ni < 0 or ni >= 4 or nj < 0 or nj >= 4:
                return None  # Out of bounds
            if new_grid[ni][nj] != '.':
                return None  # Overlap
            new_grid[ni][nj] = '#'

        return new_grid

    def count_filled_cells(shape):
        """Count the number of filled cells in a shape"""
        return sum(row.count('#') for row in shape)

    def solve_puzzle(polyominoes):
        # Get all orientations for each polyomino
        all_orientations = [get_all_orientations(p) for p in polyominoes]

        # Check total cell count
        total_cells = sum(count_filled_cells(p) for p in polyominoes)
        if total_cells != 16:
            return False

        # Try all combinations of orientations and placements
        for orient1 in all_orientations[0]:
            for i1 in range(4):
                for j1 in range(4):
                    grid1 = place_polyomino([['.' for _ in range(4)] for _ in range(4)], 
                                          orient1, i1, j1)
                    if grid1 is None:
                        continue

                    for orient2 in all_orientations[1]:
                        for i2 in range(4):
                            for j2 in range(4):
                                grid2 = place_polyomino(grid1, orient2, i2, j2)
                                if grid2 is None:
                                    continue

                                for orient3 in all_orientations[2]:
                                    for i3 in range(4):
                                        for j3 in range(4):
                                            grid3 = place_polyomino(grid2, orient3, i3, j3)
                                            if grid3 is not None:
                                                # Check if all cells are filled
                                                if all(grid3[i][j] == '#' for i in range(4) for j in range(4)):
                                                    return True
        return False

    # Read input
    polyominoes = get_input()

    # Solve
    if solve_puzzle(polyominoes):
        print("Yes")
    else:
        print("No")

