def countInfectionSequences(n, sick):
    MOD = 10**9 + 7

    # Precompute factorials and inverse factorials
    maxN = n + 2
    fact = [1] * (maxN)
    invfact = [1] * (maxN)
    for i in range(1, maxN):
        fact[i] = fact[i-1] * i % MOD
    invfact[maxN-1] = pow(fact[maxN-1], MOD-2, MOD)
    for i in range(maxN-2, -1, -1):
        invfact[i] = invfact[i+1] * (i+1) % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * invfact[b] % MOD * invfact[a-b] % MOD

    # Find all gaps of uninfected children between sick children
    gaps = []
    prev = -1
    for s in sick:
        if prev == -1:
            if s > 0:
                gaps.append((s, False))  # leftmost gap, not surrounded
        else:
            if s - prev > 1:
                gaps.append((s - prev - 1, True))  # surrounded gap
        prev = s
    if sick[-1] < n-1:
        gaps.append((n-1 - sick[-1], False))  # rightmost gap, not surrounded

    total_uninfected = n - len(sick)
    res = 1
    total = 0
    for length, surrounded in gaps:
        if length == 0:
            continue
        if surrounded:
            # For surrounded gaps, the infection can only spread from both ends,
            # so the number of ways is 2^{length-1}
            res = res * pow(2, length-1, MOD) % MOD
        # Multiply by multinomial coefficient for all gaps
        res = res * comb(total + length, length) % MOD
        total += length
    return res
