def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        print("No")
        return

    n = int(data[0])
    m = int(data[1])

    # Build adjacency list
    graph = defaultdict(list)
    edges = []

    index = 2
    for _ in range(m):
        u = int(data[index])
        v = int(data[index+1])
        w = int(data[index+2])
        index += 3
        graph[u].append((v, w))
        edges.append((u, v, w))

    # Check if all vertices are reachable from any starting point
    # First, let's find strongly connected components
    def get_strongly_connected_components():
        # Kosaraju's algorithm
        visited = [False] * (n + 1)
        stack = []

        # First DFS to fill finish order
        def dfs1(v):
            visited[v] = True
            for neighbor, _ in graph[v]:
                if not visited[neighbor]:
                    dfs1(neighbor)
            stack.append(v)

        for i in range(1, n + 1):
            if not visited[i]:
                dfs1(i)

        # Reverse graph
        rev_graph = defaultdict(list)
        for u, v, w in edges:
            rev_graph[v].append((u, w))

        # Second DFS on reversed graph
        visited = [False] * (n + 1)
        sccs = []

        def dfs2(v, component):
            visited[v] = True
            component.append(v)
            for neighbor, _ in rev_graph[v]:
                if not visited[neighbor]:
                    dfs2(neighbor, component)

        while stack:
            node = stack.pop()
            if not visited[node]:
                component = []
                dfs2(node, component)
                sccs.append(component)

        return sccs

    sccs = get_strongly_connected_components()

    # Check if we can visit all vertices
    # We need to check if the condensation graph allows visiting all SCCs
    vertex_to_scc = {}
    for i, scc in enumerate(sccs):
        for v in scc:
            vertex_to_scc[v] = i

    # Condensation graph - check reachability between SCCs
    scc_graph = defaultdict(set)
    for u, v, w in edges:
        scc_u = vertex_to_scc[u]
        scc_v = vertex_to_scc[v]
        if scc_u != scc_v:
            scc_graph[scc_u].add(scc_v)

    # Check if all vertices can be visited by checking if there's a path 
    # that can reach all SCCs from some starting SCC
    def can_visit_all_vertices():
        # For each SCC as starting point, check if we can reach all other SCCs
        for start_scc in range(len(sccs)):
            visited_scc = set()
            stack = [start_scc]

            while stack:
                curr = stack.pop()
                if curr in visited_scc:
                    continue
                visited_scc.add(curr)

                for next_scc in scc_graph[curr]:
                    if next_scc not in visited_scc:
                        stack.append(next_scc)

            # Check if all SCCs are reachable
            if len(visited_scc) == len(sccs):
                return True

        return False

    if not can_visit_all_vertices():
        print("No")
        return

    # Now find minimum weight walk that visits all vertices
    # Use Floyd-Warshall to find shortest paths between all pairs
    INF = float('inf')
    dist = [[INF] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dist[i][i] = 0

    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    # Floyd-Warshall
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][k] != INF and dist[k][j] != INF:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Check for negative cycles (though problem states there are none)
    for i in range(1, n + 1):
        if dist[i][i] < 0:
            print("No")  # This shouldn't happen according to constraints
            return

    # Now use dynamic programming with bitmasks to find minimum cost
    # dp[mask][i] = minimum cost to have visited vertices in mask and end at vertex i
    ALL_VISITED = (1 << n) - 1
    dp = {}

    # Initialize: can start at any vertex with cost 0
    for i in range(1, n + 1):
        dp[(1 << (i-1), i)] = 0

    # Expand the state space
    changed = True
    while changed:
        changed = False
        new_dp = dp.copy()

        for (mask, pos), cost in dp.items():
            # Try to go to any other vertex
            for next_pos in range(1, n + 1):
                if dist[pos][next_pos] == INF:
                    continue

                new_cost = cost + dist[pos][next_pos]
                new_mask = mask | (1 << (next_pos-1))

                state = (new_mask, next_pos)
                if state not in new_dp or new_dp[state] > new_cost:
                    new_dp[state] = new_cost
                    changed = True

        dp = new_dp

    # Find minimum cost to visit all vertices
    min_cost = INF
    for i in range(1, n + 1):
        state = (ALL_VISITED, i)
        if state in dp:
            min_cost = min(min_cost, dp[state])

    if min_cost == INF:
        print("No")
    else:
        print(min_cost)

