def getSmallestString(s):
    n = len(s)

    # Convert string to list for easier manipulation
    chars = list(s)

    # Find the first non-'a' character to start our operation
    start = -1
    for i in range(n):
        if chars[i] != 'a':
            start = i
            break

    # If all characters are 'a', we must change the last character to 'z'
    if start == -1:
        chars[n-1] = 'z'
        return ''.join(chars)

    # Extend the substring as far as possible from the start position
    # We want to include all consecutive non-'a' characters
    end = start
    while end < n and chars[end] != 'a':
        end += 1

    # Apply the operation: replace each character with the previous one
    # 'a' becomes 'z', others move back by one
    for i in range(start, end):
        if chars[i] == 'a':
            chars[i] = 'z'
        else:
            chars[i] = chr(ord(chars[i]) - 1)

    return ''.join(chars)
