def maximumEnergy(energy, k):
    n = len(energy)
    # Create an array to store the maximum energy starting from each position
    max_energy = [0] * n

    # Process each possible starting point from the end backwards
    for i in range(n - 1, -1, -1):
        # If we can jump from this position
        if i + k < n:
            max_energy[i] = energy[i] + max_energy[i + k]
        else:
            # This is the last magician in this sequence
            max_energy[i] = energy[i]

    # Return the maximum energy among all possible starting points
    return max(max_energy)
