def numberOfBeautifulIntegers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_beautiful(n):
        s = str(n)
        length = len(s)

        @lru_cache(maxsize=None)
        def dp(pos, even, odd, mod, tight, started):
            if pos == length:
                return started and even == odd and mod == 0
            res = 0
            up = int(s[pos]) if tight else 9
            for d in range(0, up + 1):
                n_even = even
                n_odd = odd
                n_started = started or d != 0
                if n_started:
                    if d % 2 == 0:
                        n_even += 1
                    else:
                        n_odd += 1
                n_mod = (mod * 10 + d) % k if n_started else 0
                n_tight = tight and (d == up)
                res += dp(pos + 1, n_even, n_odd, n_mod, n_tight, n_started)
            return res

        return dp(0, 0, 0, 0, True, False)

    return count_beautiful(high) - count_beautiful(low - 1)
