def longestValidSubstring(word, forbidden):
    forbidden_set = set(forbidden)
    n = len(word)
    max_length = 0

    # For each starting position
    for i in range(n):
        # Try each ending position
        for j in range(i, n):
            # Check if substring word[i:j+1] contains any forbidden substring
            valid = True
            for forbidden_word in forbidden_set:
                if forbidden_word in word[i:j+1]:
                    valid = False
                    break

            if valid:
                max_length = max(max_length, j - i + 1)
            else:
                # If current substring is invalid, extending it further won't help
                break

    return max_length
