def minimumDistance(points):
    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    n = len(points)
    min_max_distance = float('inf')

    # Try removing each point
    for i in range(n):
        # Calculate maximum distance among remaining points
        max_distance = 0
        remaining_points = points[:i] + points[i+1:]

        # Find maximum Manhattan distance between any two remaining points
        for j in range(len(remaining_points)):
            for k in range(j + 1, len(remaining_points)):
                distance = manhattan_distance(remaining_points[j], remaining_points[k])
                max_distance = max(max_distance, distance)

        min_max_distance = min(min_max_distance, max_distance)

    return min_max_distance
