                row.append(0)
            elif zero_count == 1:
                if val == 0:
                    prod = 1
                    for num in flat:
                        if num != 0:
                            prod = (prod * num) % MOD
                    row.append(prod)
                else:
                    row.append(0)
            else:
                # Modular inverse using Fermat's little theorem since MOD is prime
                inv = pow(val, MOD-2, MOD)
                row.append((total_product * inv) % MOD)
        result.append(row)
    return result
```

