        for i in range(3):
            if colors[i][0] == colors[i][1] == colors[i][2] and colors[i][0] != 'W':
                return colors[i][0]

        # Check columns
        for j in range(3):
            if colors[0][j] == colors[1][j] == colors[2][j] and colors[0][j] != 'W':
                return colors[0][j]

        # Check diagonals
        if colors[0][0] == colors[1][1] == colors[2][2] and colors[0][0] != 'W':
            return colors[0][0]
        if colors[0][2] == colors[1][1] == colors[2][0] and colors[0][2] != 'W':
            return colors[0][2]

        return None

    # Minimax with alpha-beta pruning
    def minimax(colors, scores, remaining_positions, is_takahashi_turn, alpha, beta):
        # Check if someone won by having 3 in a row
        winner = check_winner(colors)
        if winner:
            return (float('inf') if winner == 'R' else float('-inf'), None)

        # Check if game is over (no more moves)
        if not remaining_positions:
            # Winner is the one with higher score
            if scores[0] > scores[1]:
                return (float('inf'), None)  # Takahashi wins
            else:
                return (float('-inf'), None)  # Aoki wins

        if is_takahashi_turn:
            # Takahashi maximizes his advantage
            max_eval = float('-inf')
            best_move = None

            for pos in remaining_positions:
                i, j = pos
                new_colors = [row[:] for row in colors]
                new_colors[i][j] = 'R'
                new_scores = (scores[0] + grid[i][j], scores[1])
                new_remaining = [p for p in remaining_positions if p != pos]

                # Check if this move creates a winning line
                winner = check_winner(new_colors)
                if winner == 'R':
                    eval_score = float('inf')
                elif winner == 'B':
                    eval_score = float('-inf')
                elif not new_remaining:  # No more moves
                    if new_scores[0] > new_scores[1]:
                        eval_score = float('inf')
                    else:
                        eval_score = float('-inf')
                else:
                    eval_score, _ = minimax(new_colors, new_scores, new_remaining, False, alpha, beta)

                if eval_score > max_eval:
                    max_eval = eval_score
                    best_move = pos

                alpha = max(alpha, max_eval)
                if beta <= alpha:
                    break

            return (max_eval, best_move)
        else:
            # Aoki minimizes Takahashi's advantage
            min_eval = float('inf')
            best_move = None

            for pos in remaining_positions:
                i, j = pos
                new_colors = [row[:] for row in colors]
                new_colors[i][j] = 'B'
                new_scores = (scores[0], scores[1] + grid[i][j])
                new_remaining = [p for p in remaining_positions if p != pos]

                # Check if this move creates a winning line
                winner = check_winner(new_colors)
                if winner == 'R':
                    eval_score = float('inf')
                elif winner == 'B':
                    eval_score = float('-inf')
                elif not new_remaining:  # No more moves
                    if new_scores[0] > new_scores[1]:
                        eval_score = float('inf')
                    else:
                        eval_score = float('-inf')
                else:
                    eval_score, _ = minimax(new_colors, new_scores, new_remaining, True, alpha, beta)

                if eval_score < min_eval:
                    min_eval = eval_score
                    best_move = pos

                beta = min(beta, min_eval)
                if beta <= alpha:
                    break

            return (min_eval, best_move)

    # Initialize game state
    initial_colors = [['W' for _ in range(3)] for _ in range(3)]
    initial_scores = (0, 0)
    initial_positions = [(i, j) for i in range(3) for j in range(3)]

    # Find optimal first move for Takahashi
    result, _ = minimax(initial_colors, initial_scores, initial_positions, True, float('-inf'), float('inf'))

    # If result is positive infinity, Takahashi wins; otherwise Aoki wins
    if result == float('inf'):
        print("Takahashi")
    else:
        print("Aoki")

solve()
