def minimumChanges(s, k):
    n = len(s)

    # Precompute the cost to make each substring a semi-palindrome
    def get_semi_palindrome_cost(substring):
        length = len(substring)
        if length == 1:
            return float('inf')  # Single character cannot be semi-palindrome

        min_cost = float('inf')

        # Try all possible divisors d where 1 <= d < length and length % d == 0
        for d in range(1, length):
            if length % d != 0:
                continue

            cost = 0
            # For each residue class modulo d, check if it forms a palindrome
            for r in range(d):
                # Get characters at positions with index % d == r
                chars = []
                for i in range(r, length, d):
                    chars.append(substring[i])

                # Check how many changes needed to make this sequence a palindrome
                seq_len = len(chars)
                for j in range(seq_len // 2):
                    if chars[j] != chars[seq_len - 1 - j]:
                        cost += 1

            min_cost = min(min_cost, cost)

        return min_cost if min_cost != float('inf') else 0

    # Precompute cost for all substrings
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = get_semi_palindrome_cost(s[i:j+1])

    # Dynamic programming to find minimum cost partition
    # dp[i][p] = minimum cost to partition s[0:i] into p semi-palindromes
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for p in range(1, min(k, i) + 1):
            # Try all possible last substring ending at position i-1
            for j in range(p - 1, i):
                if j == 0 and p > 1:  # Need at least p characters for p partitions
                    continue
                if i - j >= 2:  # Substring must have length >= 2 to be semi-palindrome
                    prev_cost = dp[j][p - 1]
                    curr_cost = cost[j][i - 1]
                    if prev_cost != INF:
                        dp[i][p] = min(dp[i][p], prev_cost + curr_cost)

    return dp[n][k]
```

