    first_line = input().split()
    N = int(first_line[0])
    T_prime = first_line[1]

    S_list = []
    for _ in range(N):
        S_list.append(input().strip())

    def could_be_T(S, T_prime):
        len_S = len(S)
        len_T_prime = len(T_prime)

        # Case 1: T' is equal to T (S == T')
        if S == T_prime:
            return True

        # Case 2: T' is obtained by inserting one character into T
        # So |T'| = |T| + 1, meaning |T'| = |S| + 1
        elif len_T_prime == len_S + 1:
            i = j = 0
            diff_count = 0
            while i < len_S and j < len_T_prime:
                if S[i] == T_prime[j]:
                    i += 1
                    j += 1
                else:
                    diff_count += 1
                    j += 1  # skip the inserted character in T'

            # If we've matched all characters in S, and there was exactly one difference
            # (the inserted character), then it's valid
            if i == len_S and (diff_count == 1 or j == len_T_prime):
                return True

        # Case 3: T' is obtained by deleting one character from T
        # So |T'| = |T| - 1, meaning |T'| = |S| - 1
        elif len_T_prime == len_S - 1:
            i = j = 0
            diff_count = 0
            while i < len_S and j < len_T_prime:
                if S[i] == T_prime[j]:
                    i += 1
                    j += 1
                else:
                    diff_count += 1
                    i += 1  # skip the deleted character in S

            # If we've matched all characters in T', and there was exactly one difference
            # (the deleted character), then it's valid
            if j == len_T_prime and (diff_count == 1 or i == len_S):
                return True

        # Case 4: T' is obtained by changing one character in T
        # So |T'| = |T|, meaning |T'| = |S|
        elif len_T_prime == len_S:
            diff_count = 0
            for i in range(len_S):
                if S[i] != T_prime[i]:
                    diff_count += 1
                    if diff_count > 1:
                        break

            # Exactly one character changed
            if diff_count == 1:
                return True

        return False

    # Find all indices where S_i could be T
    result_indices = []
    for i in range(N):
        if could_be_T(S_list[i], T_prime):
            result_indices.append(i + 1)  # 1-indexed

    # Output
    print(len(result_indices))
    if result_indices:
        print(' '.join(map(str, result_indices)))

