        # Check if the 9x9 region starting at (top_row, left_col) is a valid Tak Code
        # Convert to 0-indexed
        r0, c0 = top_row - 1, left_col - 1

        # Check top-left 3x3 region - all should be black (#)
        for i in range(3):
            for j in range(3):
                if grid[r0 + i][c0 + j] != '#':
                    return False

        # Check bottom-right 3x3 region - all should be black (#)
        for i in range(3):
            for j in range(3):
                if grid[r0 + 6 + i][c0 + 6 + j] != '#':
                    return False

        # Check the 14 cells adjacent to top-left 3x3 region - all should be white (.)
        # These are: right of top-left 3x3 (3 cells), below top-left 3x3 (3 cells), and diagonally down-right (1 cell)
        # But actually, it's all cells that are adjacent (including diagonally) to the 3x3 region but not part of it
        adjacent_positions = []

        # Cells to the right of the 3x3 block
        for i in range(3):
            adjacent_positions.append((i, 3))

        # Cells below the 3x3 block  
        for j in range(3):
            adjacent_positions.append((3, j))

        # Cell diagonally down-right
        adjacent_positions.append((3, 3))

        for dr, dc in adjacent_positions:
            if grid[r0 + dr][c0 + dc] != '.':
                return False

        # Check the 14 cells adjacent to bottom-right 3x3 region - all should be white (.)
        adjacent_positions_br = []

        # Cells to the left of the bottom-right 3x3 block
        for i in range(3):
            adjacent_positions_br.append((i, -1))

        # Cells above the bottom-right 3x3 block
        for j in range(3):
            adjacent_positions_br.append((-1, j))

        # Cell diagonally up-left
        adjacent_positions_br.append((-1, -1))

        for dr, dc in adjacent_positions_br:
            if grid[r0 + 6 + dr][c0 + 6 + dc] != '.':
                return False

        return True

    # Find all valid 9x9 regions
    results = []
    for i in range(1, N - 7):  # top row can be from 1 to N-8 (inclusive)
        for j in range(1, M - 7):  # left column can be from 1 to M-8 (inclusive)
