    def can_fit(width):
        lines_used = 1
        current_line_width = 0

        for i, word_width in enumerate(L):
            if i == 0:
                # First word must be at the beginning of the line
                if word_width > width:
                    return False
                current_line_width = word_width
            else:
                # Try to place the word after a space (width 1) from the previous word
                if current_line_width + 1 + word_width <= width:
                    current_line_width += 1 + word_width
                else:
                    # Need to start a new line
                    lines_used += 1
                    if lines_used > m:
                        return False
                    current_line_width = word_width
                    if word_width > width:
                        return False

        return True

    # Binary search on the answer
    left = max(L)  # Minimum possible width must be at least the largest word
    right = sum(L) + (n - 1)  # Maximum possible width is all words in one line with spaces

    while left < right:
        mid = (left + right) // 2
        if can_fit(mid):
            right = mid
        else:
            left = mid + 1

    print(left)

