def kthSmallestAmount(coins, k):
    def count_multiples(x):
        # Count how many multiples <= x using inclusion-exclusion principle
        total = 0
        n = len(coins)

        # Iterate through all subsets of coins
        for mask in range(1, 1 << n):
            lcm_val = 1
            bit_count = 0

            for i in range(n):
                if mask & (1 << i):
                    # Calculate LCM of selected coins in this subset
                    import math
                    lcm_val = lcm_val * coins[i] // math.gcd(lcm_val, coins[i])
                    bit_count += 1

            # Apply inclusion-exclusion: add for odd number of elements, subtract for even
            if bit_count % 2 == 1:
                total += x // lcm_val
            else:
                total -= x // lcm_val

        return total

    # Binary search on the answer
    left, right = 1, k * min(coins)

    while left < right:
        mid = (left + right) // 2
        if count_multiples(mid) < k:
            left = mid + 1
        else:
            right = mid

    return left
