import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    # Read N and Q
    N = int(data[0])
    Q = int(data[1])

    # Read the pattern P
    P = []
    index = 2
    for i in range(N):
        row = data[index + i]
        P.append(row)

    # Precompute prefix sum for the N x N pattern
    # Count black cells in each position of the pattern
    prefix = [[0] * (N + 1) for _ in range(N + 1)]

    for i in range(N):
        for j in range(N):
            prefix[i + 1][j + 1] = prefix[i][j + 1] + prefix[i + 1][j] - prefix[i][j] + (1 if P[i][j] == 'B' else 0)

    total_black_in_pattern = prefix[N][N]

    def count_black_in_rectangle(a, b, c, d):
        # Count black squares in rectangle from (a,b) to (c,d)
        if a > c or b > d:
            return 0

        result = 0

        # Full patterns
        full_rows = (c - a + 1) // N
        full_cols = (d - b + 1) // N

        if full_rows > 0 and full_cols > 0:
            result += full_rows * full_cols * total_black_in_pattern

        # Remaining partial patterns
        start_row = a % N
        start_col = b % N
        end_row = c % N
        end_col = d % N

        width = d - b + 1
        height = c - a + 1

        # Handle the case when the rectangle spans multiple pattern blocks
        if height >= N or width >= N:
            # Count complete full rows first
            if full_rows > 0:
                remaining_height = height - full_rows * N
                # Top remaining part (if any)
                if a // N != c // N:  # spans multiple row blocks
                    for i in range(start_row, N):
                        row = (a + i - start_row) % N
                        for j in range(width):
                            col = (b + j) % N
                            if P[row][col] == 'B':
                                result += 1
                    # Bottom remaining part (if any)
                    for i in range(remaining_height):
                        row = i
                        for j in range(width):
                            col = (b + j) % N
                            if P[row][col] == 'B':
                                result += 1
                else:  # all in same row block
                    for i in range(height):
                        row = (a + i) % N
                        for j in range(width):
                            col = (b + j) % N
                            if P[row][col] == 'B':
                                result += 1
            elif full_cols > 0:
                # Similar logic for columns
                remaining_width = width - full_cols * N
                if b // N != d // N:  # spans multiple column blocks
                    # Left remaining part
                    for j in range(start_col, N):
                        col = j
                        for i in range(height):
                            row = (a + i) % N
                            if P[row][col] == 'B':
                                result += 1
                    # Right remaining part
                    for j in range(remaining_width):
                        col = j
                        for i in range(height):
                            row = (a + i) % N
                            if P[row][col] == 'B':
                                result += 1
                else:
                    for i in range(height):
                        row = (a + i) % N
                        for j in range(width):
                            col = (b + j) % N
                            if P[row][col] == 'B':
                                result += 1
            else:
                # No full patterns, just count directly
                for i in range(height):
                    for j in range(width):
                        row = (a + i) % N
                        col = (b + j) % N
                        if P[row][col] == 'B':
                            result += 1
        else:
            # Small rectangle, count directly
            for i in range(height):
                for j in range(width):
                    row = (a + i) % N
                    col = (b + j) % N
                    if P[row][col] == 'B':
                        result += 1

        return result

    # Process queries
    index = 2 + N
    results = []
    for _ in range(Q):
        a = int(data[index])
        b = int(data[index + 1])
        c = int(data[index + 2])
        d = int(data[index + 3])
        index += 4

        result = count_black_in_rectangle(a, b, c, d)
        results.append(str(result))

    print('\n'.join(results))

