def maxPalindromes(words):
    # Count frequency of each character across all words
    char_count = {}
    for word in words:
        for char in word:
            char_count[char] = char_count.get(char, 0) + 1

    # Sort words by length (ascending) to maximize palindromes
    word_lengths = sorted([len(word) for word in words])

    palindromes = 0
    remaining_chars = char_count.copy()

    # For each word length, try to form a palindrome
    for length in word_lengths:
        # Check if we can form a palindrome of this length
        odd_count = 0
        temp_chars = remaining_chars.copy()

        # Calculate how many characters would have odd frequency in a palindrome
        for char, count in temp_chars.items():
            if count % 2 == 1:
                odd_count += 1

        # A palindrome can have at most one character with odd frequency (the middle character)
        if odd_count <= 1 and sum(temp_chars.values()) >= length:
            # We can form a palindrome of this length
            palindromes += 1

            # Use up the characters needed for this palindrome
            chars_needed = length
            for char in sorted(temp_chars.keys()):
                while temp_chars[char] > 0 and chars_needed > 0:
                    temp_chars[char] -= 1
                    chars_needed -= 1
                    if temp_chars[char] == 0:
                        break

            # Update remaining characters
            remaining_chars = temp_chars

    return palindromes
