def punishmentNumber(n):
    def can_partition(s, target, current_sum, index):
        if index == len(s):
            return current_sum == target

        for i in range(index + 1, len(s) + 1):
            # Extract substring from index to i
            num = int(s[index:i])
            # Recursively check if we can reach the target with this partition
            if can_partition(s, target, current_sum + num, i):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        square = i * i
        square_str = str(square)

        # Check if we can partition the square string to sum up to i
        if can_partition(square_str, i, 0, 0):
            total += square

    return total
