import sys

def solve():
    def get_ancestors(v):
        """Get all ancestors of vertex v including v itself."""
        ancestors = []
        while v >= 1:
            ancestors.append(v)
            v //= 2
        return ancestors

    def get_distance(u, v):
        """Get distance between vertices u and v."""
        # Get paths from root to u and v
        path_u = get_ancestors(u)
        path_v = get_ancestors(v)

        # Find LCA (lowest common ancestor)
        i = len(path_u) - 1
        j = len(path_v) - 1
        while i >= 0 and j >= 0 and path_u[i] == path_v[j]:
            i -= 1
            j -= 1

        # Distance is the sum of distances from each node to LCA
        return (i + 1) + (j + 1)

    def count_vertices_at_distance(n, x, k):
        if k == 0:
            return 1 if x <= n else 0

        # For large N, we need a more efficient approach
        # We'll use BFS-like level traversal but with mathematical properties

        # Level of a node i is floor(log2(i)) + 1, or simply the number of times 
        # we can divide by 2 until we reach 1
        def get_level(node):
            level = 0
            temp = node
            while temp > 1:
                temp //= 2
                level += 1
            return level

        target_level = get_level(x)
        x_level = target_level

        # Instead of traversing entire tree, let's think about the structure:
        # This is essentially a complete binary tree with some nodes possibly missing at the last level

        count = 0

        # For K=0, only X itself
        if k == 0:
            return 1 if x <= n else 0

        # For larger K, we need to find all nodes at distance K from X
        # We can do this by considering two cases:
        # 1. Going up from X and then down to other branches
        # 2. Going down from X to its descendants

        # Case 1: Go up from X and then down
        current = x
        up_steps = 0

        while current >= 1 and up_steps <= k:
            remaining = k - up_steps

            # From current node, go down 'remaining' steps
            # But avoid going back the way we came up
            if remaining == 0:
                if current <= n:
                    count += 1
            else:
                # We're at some ancestor of X, now go down in other branches
                # First, determine which child we came from
                came_from_left = (current * 2 == x_original_parent(current, up_steps))

                # Explore left subtree if we didn't come from left or if remaining > 1
                if current * 2 <= n and (not came_from_left or remaining > 1):
                    # Count nodes at depth 'remaining' in left subtree
                    left_start = current * 2
                    if remaining == 1:
                        if left_start <= n:
                            count += 1
                    else:
                        # Multiple levels down
                        min_node = left_start << (remaining - 1)
                        max_node = ((left_start + 1) << (remaining - 1)) - 1
                        if min_node <= n:
                            count += min(max_node, n) - min_node + 1

                # Similarly for right subtree
                if current * 2 + 1 <= n and (came_from_left or remaining > 1):
                    right_start = current * 2 + 1
                    if remaining == 1:
                        if right_start <= n:
                            count += 1
                    else:
                        min_node = right_start << (remaining - 1)
                        max_node = ((right_start + 1) << (remaining - 1)) - 1
                        if min_node <= n:
                            count += min(max_node, n) - min_node + 1

            # Move up one level
            if current == 1:
                break
            current //= 2
            up_steps += 1

        # Remove double counting of X itself when k=0
        if k == 0:
            count -= 1  # We'll add it back later if valid

        # Case 2: Direct descendants of X at exactly distance K
        if k > 0:
            min_descendant = x << k
            max_descendant = ((x + 1) << k) - 1
            if min_descendant <= n:
                count += min(max_descendant, n) - min_descendant + 1

        return count

    def x_original_parent(x, up_steps):
        """Get the original parent from which we came after up_steps"""
        if up_steps == 0:
            return x
        result = x
        for _ in range(up_steps):
            result //= 2
        return result

    def solve_case(n, x, k):
        if k == 0:
            return 1 if x <= n else 0

        # Special handling for very large inputs using bit manipulation
        count = 0

        # Count descendants of x at distance k
        min_desc = x * (1 << k)
        max_desc = (x + 1) * (1 << k) - 1

        if min_desc <= n:
            count += min(max_desc, n) - min_desc + 1

        # Count ancestors and their other subtrees
        current = x
        for up_steps in range(1, k + 1):
            if current == 1:
                # At root, check both children subtrees for remaining distance
                remaining = k - up_steps
                if remaining >= 0:
                    if remaining == 0:
                        count += 1  # the root itself
                    else:
                        # Both left and right subtrees
                        for child in [1]:
                            for next_child in [2, 3]:  # children of root
                                min_node = next_child * (1 << (remaining - 1)) if remaining > 0 else next_child
                                max_node = (next_child + 1) * (1 << (remaining - 1)) - 1 if remaining > 0 else next_child
                                if min_node <= n and remaining >= 0:
                                    count += min(max_node, n) - min_node + 1
                break
            else:
                parent = current // 2
                remaining = k - up_steps

                if remaining == 0:
                    count += 1  # count the ancestor itself
                elif remaining > 0:
                    # Check sibling subtree
                    sibling = parent * 2 + 1 if parent * 2 == current else parent * 2
                    if sibling <= n:
                        if remaining == 1:
                            count += 1
                        else:
                            min_node = sibling * (1 << (remaining - 1))
                            max_node = (sibling + 1) * (1 << (remaining - 1)) - 1
                            if min_node <= n:
                                count += min(max_node, n) - min_node + 1

                current = parent

        return count

    input_lines = sys.stdin.read().splitlines()
    t = int(input_lines[0])

    for i in range(t):
        line = input_lines[1 + i]
        n, x, k = map(int, line.split())
        result = solve_case(n, x, k)
        print(result)

solve()
```

