def countCompleteSubstrings(word, k):
    def isValidSubstring(s, k):
        # Check if each character occurs exactly k times
        char_count = {}
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1

        # Check if all characters appear exactly k times
        if not all(count == k for count in char_count.values()):
            return False

        # Check if difference between adjacent characters is at most 2
        for i in range(len(s) - 1):
            if abs(ord(s[i]) - ord(s[i + 1])) > 2:
                return False

        return True

    n = len(word)
    count = 0

    # Check all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = word[i:j]
            # Optimization: if length is not a multiple of k, skip
            if len(substring) % k != 0:
                continue
            # Only check if the length constraint could possibly be satisfied
            if len(substring) <= 26 * k:  # At most 26 different characters
                if isValidSubstring(substring, k):
                    count += 1

    return count
