def canSortArray(nums):
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Group elements by their set bit count
    groups = []
    current_group = []
    current_bit_count = -1

    for num in nums:
        bit_count = count_set_bits(num)
        if bit_count == current_bit_count:
            current_group.append(num)
        else:
            if current_group:
                groups.append(current_group)
            current_group = [num]
            current_bit_count = bit_count

    if current_group:
        groups.append(current_group)

    # For each group, check if sorting the group maintains relative order with adjacent groups
    sorted_nums = []
    for group in groups:
        sorted_group = sorted(group)
        sorted_nums.extend(sorted_group)

    # Check if the final array is sorted
    return sorted_nums == sorted(nums)
