def beautifulIndices(s: str, a: str, b: str, k: int) -> list:
    # Find all start indices where substring a occurs
    a_indices = []
    for i in range(len(s) - len(a) + 1):
        if s[i:i+len(a)] == a:
            a_indices.append(i)
    # Find all start indices where substring b occurs
    b_indices = []
    for j in range(len(s) - len(b) + 1):
        if s[j:j+len(b)] == b:
            b_indices.append(j)
    # For each a_index, check if there is a b_index within distance k
    res = []
    b_ptr = 0
    b_len = len(b_indices)
    for i in a_indices:
        # Move b_ptr to the first b_index >= i - k
        while b_ptr < b_len and b_indices[b_ptr] < i - k:
            b_ptr += 1
        # Check if any b_index in [i-k, i+k]
        found = False
        check_ptr = b_ptr
        while check_ptr < b_len and b_indices[check_ptr] <= i + k:
            found = True
            break
        if found:
            res.append(i)
