def canTraverseAllPairs(nums):
    from math import gcd
    from collections import defaultdict

    n = len(nums)
    if n == 1:
        return True

    # If any element is 1, it cannot connect to anything else
    if 1 in nums:
        return False

    # Union-Find (Disjoint Set Union) implementation
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    # Sieve to get smallest prime factor for each number up to max(nums)
    max_num = max(nums)
    spf = [0] * (max_num + 1)
    for i in range(2, max_num + 1):
        if spf[i] == 0:
            for j in range(i, max_num + 1, i):
                if spf[j] == 0:
                    spf[j] = i

    # Map from prime to list of indices in nums
    prime_to_indices = defaultdict(list)

    for idx, num in enumerate(nums):
        x = num
        factors = set()
        while x > 1:
            p = spf[x]
            factors.add(p)
            while x % p == 0:
                x //= p
        for p in factors:
            prime_to_indices[p].append(idx)

    # For each prime, union all indices that share this prime
    for indices in prime_to_indices.values():
        for i in range(1, len(indices)):
            union(indices[0], indices[i])

    # Check if all indices are in the same component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
