def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    R = data[1]
    C = data[2]

    # For small constraints (N between 3 and 5), we can use backtracking
    grid = [['.' for _ in range(N)] for _ in range(N)]

    def is_valid():
        # Check if current grid satisfies all conditions
        # Check rows
        for i in range(N):
            row_chars = [grid[i][j] for j in range(N) if grid[i][j] != '.']
            if len(row_chars) != 3 or set(row_chars) != {'A', 'B', 'C'}:
                return False

            # Check leftmost character
            leftmost = None
            for j in range(N):
                if grid[i][j] != '.':
                    leftmost = grid[i][j]
                    break
            if leftmost != R[i]:
                return False

        # Check columns
        for j in range(N):
            col_chars = [grid[i][j] for i in range(N) if grid[i][j] != '.']
            if len(col_chars) != 3 or set(col_chars) != {'A', 'B', 'C'}:
                return False

            # Check topmost character
            topmost = None
            for i in range(N):
                if grid[i][j] != '.':
                    topmost = grid[i][j]
                    break
            if topmost != C[j]:
                return False

        return True

    def count_char_in_row(row, char):
        return sum(1 for j in range(N) if grid[row][j] == char)

    def count_char_in_col(col, char):
        return sum(1 for i in range(N) if grid[i][col] == char)

    def backtrack(pos):
        if pos == N * N:
            return is_valid()

        row = pos // N
        col = pos % N

        # Try leaving the cell empty
        if backtrack(pos + 1):
            return True

        # Try placing A, B, or C
        for char in ['A', 'B', 'C']:
            # Check if we can place this character
            if count_char_in_row(row, char) < 1 and count_char_in_col(col, char) < 1:
                grid[row][col] = char
                if backtrack(pos + 1):
                    return True
                grid[row][col] = '.'

        return False

    # First check basic feasibility
    # Each row must have its leftmost non-empty cell matching R[i]
    # Each column must have its topmost non-empty cell matching C[j]

    # Also check if the required leftmost/topmost characters are possible
    if any(R.count(char) > N - 2 for char in ['A', 'B', 'C']) or any(C.count(char) > N - 2 for char in ['A', 'B', 'C']):
        print("No")
        return

    # Use backtracking to find a solution
    if backtrack(0):
        print("Yes")
        for i in range(N):
            print(''.join(grid[i]))
    else:
        print("No")

solve()
