def lengthOfLongestSubsequence(nums, target):
    # dp[i] represents the maximum length of subsequence that sums to i
    # Initialize with -1 to indicate unreachable states
    dp = [-1] * (target + 1)
    dp[0] = 0  # Empty subsequence has sum 0 and length 0

    for num in nums:
        # Traverse backwards to avoid using updated values in the same iteration
        for t in range(target, num - 1, -1):
            if dp[t - num] != -1:
                dp[t] = max(dp[t], dp[t - num] + 1)

    return dp[target]
