def minimumTimeToInitialState(word: str, k: int) -> int:
    n = len(word)
    for t in range(1, n + 1):
        # After t operations, the string is rotated left by (k * t) % n
        shift = (k * t) % n
        # If shift is 0, the string is back to its original position
        if shift == 0:
            return t
        # Check if the rotated string can be made equal to the original by any choice of added characters
        # This is only possible if the substring word[shift:] == word[:n-shift]
        if word[shift:] == word[:n-shift]:
            return t
    return n  # Fallback, should not be reached due to constraints

