def maximumSumOfSquares(nums, k):
    MOD = 10**9 + 7
    # Count the number of set bits at each position (up to 30 bits for 10^9)
    bit_counts = [0] * 32
    for num in nums:
        for b in range(32):
            if num & (1 << b):
                bit_counts[b] += 1

    # To maximize the sum of squares, we want to create k numbers with as many high bits as possible
    # Greedily assign bits to k numbers
    result_nums = [0] * k
    for b in range(31, -1, -1):
        cnt = bit_counts[b]
        for i in range(cnt):
            result_nums[i % k] |= (1 << b)

    # Calculate the sum of squares
    ans = 0
    for num in result_nums:
        ans = (ans + num * num) % MOD
    return ans
