```python
import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    idx = 0
    N = int(data[idx]); idx += 1
    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1

    tiles = []
    for _ in range(N):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        tiles.append((a, b))

    grid = [[False] * W for _ in range(H)]

    def find_empty():
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return None

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for dr in range(h):
            for dc in range(w):
                if grid[r + dr][c + dc]:
                    return False
        return True

    def place_tile(r, c, h, w, value):
        for dr in range(h):
            for dc in range(w):
                grid[r + dr][c + dc] = value

    def dfs(used_mask):
        pos = find_empty()
        if pos is None:
            return True

        r, c = pos
        for i in range(N):
            if used_mask & (1 << i):
                continue
            for h, w in [(tiles[i][0], tiles[i][1]), (tiles[i][1], tiles[i][0])]:
                if can_place(r, c, h, w):
                    place_tile(r, c, h, w, True)
                    if dfs(used_mask | (1 << i)):
                        return True
                    place_tile(r, c, h, w, False)
        return False

    if dfs(0):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
