def canTraverseAllPairs(nums):
    if len(nums) == 1:
        return True

    # If there's a 1 in the array, it can only connect to itself (gcd(1, x) = 1 for all x > 1)
    if 1 in nums:
        return False

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Union-Find data structure
    parent = list(range(len(nums)))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # For each pair of indices, check if they can be connected
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if gcd(nums[i], nums[j]) > 1:
                union(i, j)

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, len(nums)):
        if find(i) != root:
            return False

    return True
