We can solve this by building a graph where each index is a node, and edges exist between indices if gcd(nums[i], nums[j]) > 1.  
However, checking all pairs would be O(n²), which is too slow for n up to 10⁵.

Instead, we can think in terms of prime factors:  
If two numbers share a prime factor, they are connected via that prime.  
We can build a union-find (disjoint set union) structure where:
- Each number’s prime factors link the number to other numbers with the same prime factors.
- We union indices via their prime factors.

**Approach:**
1. For each index `i` and its value `num`, factorize `num` into distinct primes.
2. For each prime factor `p`, link `i` with `p` in DSU (but primes are not indices, so we offset them by `n` to avoid collision with indices).
3. After processing all numbers, check if all indices are in the same connected component.

**Complexity:**
- Factorization per number is O(√num), but since num ≤ 10⁵, it’s acceptable.
- DSU operations are nearly O(1).

Here’s the implementation:

```python
from math import isqrt
from typing import List

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # If any number is 1, gcd with any other number is 1, so impossible unless n == 1
    if any(x == 1 for x in nums):
        return False

    max_val = max(nums)

    # Smallest prime factor sieve
    spf = list(range(max_val + 1))
    for i in range(2, isqrt(max_val) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def get_prime_factors(x):
        factors = set()
        while x > 1:
            p = spf[x]
            factors.add(p)
            while x % p == 0:
                x //= p
        return factors

    # DSU size: n indices + offset for primes
    # We'll map primes to indices offset by n
    prime_to_id = {}
    prime_counter = n

    dsu = DSU(n + max_val + 5)  # enough space for primes up to max_val

    for i, num in enumerate(nums):
        primes = get_prime_factors(num)
        for p in primes:
            if p not in prime_to_id:
                prime_to_id[p] = prime_counter
                prime_counter += 1
            dsu.union(i, prime_to_id[p])

    root = dsu.find(0)
    for i in range(1, n):
        if dsu.find(i) != root:
            return False
    return True
```

